-- Начальная схема Charka (снята с JPA-сущностей на 2026-10-29).
-- Пишем переносимый SQL: те же миграции гоняются в тестах на H2 в режиме PostgreSQL.

-- Campaign использует @GeneratedValue по умолчанию → последовательность Hibernate с шагом 50
CREATE SEQUENCE campaign_seq START WITH 1 INCREMENT BY 50;

CREATE TABLE campaign
(
    id                 BIGINT       NOT NULL PRIMARY KEY,
    name               VARCHAR(255),
    start_date         DATE,
    current_date_value DATE
);

CREATE TABLE chronicle
(
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(255),
    start_date  DATE,
    end_date    DATE,
    campaign_id BIGINT REFERENCES campaign (id)
);

CREATE TABLE character
(
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(255),
    birth_date  DATE,
    campaign_id BIGINT REFERENCES campaign (id)
);

CREATE TABLE wound
(
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name         VARCHAR(255),
    severity     BIGINT,
    date         DATE,
    character_id BIGINT REFERENCES character (id)
);

CREATE TABLE inventory
(
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name         VARCHAR(255),
    character_id BIGINT REFERENCES character (id)
);

CREATE TABLE item
(
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name         VARCHAR(255),
    quantity     INTEGER,
    cost         INTEGER,
    description  VARCHAR(255),
    inventory_id BIGINT REFERENCES inventory (id)
);

CREATE TABLE money
(
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name           VARCHAR(255),
    amount         BIGINT,
    operation_date DATE,
    character_id   BIGINT REFERENCES character (id)
);

CREATE TABLE note
(
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name         VARCHAR(255),
    text         VARCHAR(1000),
    created_at   TIMESTAMP(6),
    character_id BIGINT REFERENCES character (id)
);

CREATE TABLE note_category
(
    id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(255)
);

CREATE TABLE note_category_link
(
    note_id     BIGINT NOT NULL REFERENCES note (id),
    category_id BIGINT NOT NULL REFERENCES note_category (id),
    PRIMARY KEY (note_id, category_id)
);

CREATE TABLE counter
(
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name          VARCHAR(255),
    counter_value INTEGER,
    type          VARCHAR(255),
    character_id  BIGINT REFERENCES character (id)
);

CREATE TABLE counter_attribute
(
    counter_id BIGINT       NOT NULL REFERENCES counter (id),
    attr_key   VARCHAR(255) NOT NULL,
    attr_value INTEGER,
    PRIMARY KEY (counter_id, attr_key)
);
